import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.B02wg2PO.js";const u=JSON.parse('{"title":"Reflex Rules","description":"","frontmatter":{},"headers":[],"relativePath":"reference/reflex-rules.md","filePath":"reference/reflex-rules.md"}'),r={name:"reference/reflex-rules.md"};function c(i,e,n,s,h,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="reflex-rules" tabindex="-1">Reflex Rules <a class="header-anchor" href="#reflex-rules" aria-label="Permalink to &quot;Reflex Rules&quot;">​</a></h1><p>Field reference for <code>Reflex</code>, <code>Event</code>, and the matching vocabulary .</p><h2 id="reflex" tabindex="-1"><code>Reflex</code> <a class="header-anchor" href="#reflex" aria-label="Permalink to &quot;`Reflex`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>Rule id</td></tr><tr><td><code>orgId?</code></td><td><code>string</code></td><td>Owning org; matching is scoped to same-org rules</td></tr><tr><td><code>createdBy?</code></td><td><code>string</code></td><td>Fires act <strong>as</strong> this user — their budget and permissions govern the fired run</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td>Short human name; also used as the fired run&#39;s title</td></tr><tr><td><code>enabled</code></td><td><code>boolean</code></td><td>The kill switch</td></tr><tr><td><code>source</code></td><td><code>string</code></td><td>Event family to listen on</td></tr><tr><td><code>type</code></td><td><code>string</code></td><td>Event type; <code>&#39;*&#39;</code> matches any type within the source</td></tr><tr><td><code>match</code></td><td><code>MatchNode</code></td><td>Boolean condition tree over the payload (a legacy array = implicit AND)</td></tr><tr><td><code>action</code></td><td><code>ActionSpec</code></td><td>What to do when it fires</td></tr><tr><td><code>brief</code></td><td><code>string</code></td><td>Prompt/message/URL template. Supports <code>{{payload.x}}</code> and <code>{{actor}}</code></td></tr><tr><td><code>project?</code></td><td><code>string</code></td><td>Registry project the fired run is scoped to</td></tr></tbody></table><h3 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Effect</th></tr></thead><tbody><tr><td><code>cooldownSec?</code></td><td>Minimum seconds between fires</td></tr><tr><td><code>dedupKey?</code></td><td>Template rendered per event; a repeated key within a TTL window is skipped</td></tr><tr><td><code>maxFires?</code></td><td>Auto-disable after this many total fires</td></tr><tr><td><code>requireApproval?</code></td><td>Park the fire for the operator to approve/deny before the action runs</td></tr></tbody></table><h3 id="bookkeeping" tabindex="-1">Bookkeeping <a class="header-anchor" href="#bookkeeping" aria-label="Permalink to &quot;Bookkeeping&quot;">​</a></h3><p><code>fireCount?</code>, <code>createdAt</code>, <code>updatedAt</code>, <code>lastFiredAt?</code>, <code>lastRunId?</code>, <code>lastSkippedAt?</code>, <code>lastSkipReason?</code>, <code>lastError?</code>.</p><h2 id="event" tabindex="-1"><code>Event</code> <a class="header-anchor" href="#event" aria-label="Permalink to &quot;`Event`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>Unique — used for dedup / idempotency</td></tr><tr><td><code>at</code></td><td><code>number</code></td><td>Epoch ms</td></tr><tr><td><code>source</code></td><td><code>string</code></td><td><code>run</code> | <code>agent</code> | <code>stripe</code> | <code>github</code> | <code>generic</code> | …</td></tr><tr><td><code>type</code></td><td><code>string</code></td><td>e.g. <code>run.finished</code>, <code>payment_intent.succeeded</code></td></tr><tr><td><code>actor?</code></td><td><code>string</code></td><td>Run title, sender handle, repo…</td></tr><tr><td><code>payload</code></td><td><code>Record&lt;string, unknown&gt;</code></td><td>Normalized, matchable fields</td></tr><tr><td><code>raw?</code></td><td><code>unknown</code></td><td>The untouched original, kept for audit / re-parse</td></tr><tr><td><code>runId?</code></td><td><code>string</code></td><td>Set when the event originated inside a run (chaining)</td></tr><tr><td><code>depth?</code></td><td><code>number</code></td><td>Chain depth; the bus loop-guard caps it</td></tr><tr><td><code>orgId?</code></td><td><code>string</code></td><td>Owning org</td></tr></tbody></table><h2 id="built-in-run-events" tabindex="-1">Built-in run events <a class="header-anchor" href="#built-in-run-events" aria-label="Permalink to &quot;Built-in run events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Run transition</th><th>Event type</th></tr></thead><tbody><tr><td><code>done</code></td><td><code>run.finished</code></td></tr><tr><td><code>error</code></td><td><code>run.failed</code></td></tr><tr><td><code>awaiting_input</code> <strong>with a pending approval gate</strong></td><td><code>run.needs_approval</code></td></tr></tbody></table><p>Plain <code>awaiting_input</code>, <code>paused</code>, and <code>cancelled</code> emit no reflex event.</p><h2 id="operators" tabindex="-1">Operators <a class="header-anchor" href="#operators" aria-label="Permalink to &quot;Operators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operator</th><th>Applies to</th><th>Notes</th></tr></thead><tbody><tr><td><code>eq</code> / <code>neq</code></td><td>any</td><td>Strict equality (<code>===</code> / <code>!==</code>)</td></tr><tr><td><code>gt</code> <code>gte</code> <code>lt</code> <code>lte</code></td><td>numbers</td><td>Both sides must be numbers, else false</td></tr><tr><td><code>between</code></td><td>numbers</td><td><code>value</code> is <code>[min, max]</code>, inclusive</td></tr><tr><td><code>contains</code></td><td>string, array</td><td>Substring for strings; membership for arrays</td></tr><tr><td><code>startsWith</code> / <code>endsWith</code></td><td>string</td><td>Both sides must be strings</td></tr><tr><td><code>matches</code></td><td>string</td><td>Regex test. An invalid pattern returns false (fails closed)</td></tr><tr><td><code>matchesI</code></td><td>string</td><td>Case-insensitive regex</td></tr><tr><td><code>in</code></td><td>any</td><td><code>value</code> must be an array containing the field</td></tr><tr><td><code>exists</code></td><td>any</td><td>Not <code>undefined</code> and not <code>null</code></td></tr><tr><td><code>changed</code></td><td>any</td><td>Differs from the last value <strong>this reflex</strong> saw for this field. First sighting counts as changed</td></tr></tbody></table><p><code>field</code> is a dot-path resolved into the payload (<code>user.plan</code>, <code>amount</code>, <code>from</code>). A path that does not resolve yields <code>undefined</code>, which only <code>exists</code> and <code>changed</code> treat specially.</p><h2 id="matchnode" tabindex="-1"><code>MatchNode</code> <a class="header-anchor" href="#matchnode" aria-label="Permalink to &quot;`MatchNode`&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MatchNode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Condition</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 // leaf</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">all</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MatchNode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[] }      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// AND</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">any</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MatchNode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[] }      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// OR</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">not</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MatchNode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> };       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// NOT</span></span></code></pre></div><h2 id="actionspec" tabindex="-1"><code>ActionSpec</code> <a class="header-anchor" href="#actionspec" aria-label="Permalink to &quot;`ActionSpec`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shape</th><th>Use</th></tr></thead><tbody><tr><td><code>startRun</code></td><td><code>{ kind: &#39;startRun&#39; }</code></td><td>Open a new run from <code>brief</code></td></tr><tr><td><code>sendToRun</code></td><td><code>{ kind: &#39;sendToRun&#39;, runId }</code></td><td>Send <code>brief</code> into an existing run</td></tr><tr><td><code>notify</code></td><td><code>{ kind: &#39;notify&#39; }</code></td><td>Tell the operator</td></tr><tr><td><code>emitEvent</code></td><td><code>{ kind: &#39;emitEvent&#39;, event: { source, type, actor?, payload? } }</code></td><td>Chain another event</td></tr><tr><td><code>callAgent</code></td><td><code>{ kind: &#39;callAgent&#39;, agent }</code></td><td>Hand one bounded task to a custom agent</td></tr><tr><td><code>webhookOut</code></td><td><code>{ kind: &#39;webhookOut&#39;, url, method?, headers? }</code></td><td>POST/PUT outbound</td></tr></tbody></table><h2 id="console-records" tabindex="-1">Console records <a class="header-anchor" href="#console-records" aria-label="Permalink to &quot;Console records&quot;">​</a></h2><p><strong><code>ReflexFire</code></strong> — <code>at</code>, <code>reflexId</code>, <code>reflexName</code>, <code>source</code>, <code>type</code>, <code>status</code> (<code>fired</code> | <code>skipped</code> | <code>pending</code> | <code>denied</code> | <code>error</code>), <code>detail?</code>, <code>runId?</code>.</p><p><strong><code>RecentEvent</code></strong> — <code>at</code>, <code>source</code>, <code>type</code>, <code>actor?</code>, and <code>matched</code> (how many reflexes matched it). This is the field that answers &quot;did my event arrive but match nothing?&quot;.</p><p><strong><code>PendingReflexFire</code></strong> — a fire parked on <code>requireApproval</code>, carrying the full <code>event</code> and a human <code>summary</code> of what will happen if approved.</p><p>See also: <a href="/docs/concepts/reflexes-and-events">Reflexes &amp; Events</a> · <a href="/docs/guides/building-a-reflex">Building a Reflex</a></p>',25)])])}const k=t(r,[["render",c]]);export{u as __pageData,k as default};
